/* ---------- Task table ---------- */
.ttx{overflow:hidden;position:relative;container:ttx/inline-size}
/* the header holds the table's name and a summary, or, while rows are picked, what you can do to them */
.ttx-hd{position:relative;height:50px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ttx-ti,.ttx-sb{position:absolute;inset:0;display:flex;align-items:center;transition:opacity .28s var(--dm-ease),transform .45s var(--dm-ease),filter .28s var(--dm-ease)}
.ttx-ti{gap:10px;padding:0 var(--dm-s-4)}
.ttx-ti b{font-size:13.5px;font-weight:500}
.ttx-sum{font-size:12.5px}
.ttx-sb{gap:2px;padding:0 10px 0 var(--dm-s-4);opacity:0;transform:translateY(10px);filter:blur(3px);pointer-events:none}
.ttx.selecting .ttx-ti{opacity:0;transform:translateY(-10px);filter:blur(3px);pointer-events:none}
.ttx.selecting .ttx-sb{opacity:1;transform:none;filter:none;pointer-events:auto}
.ttx-n{margin-right:var(--dm-s-2);font-size:13px;font-weight:500;white-space:nowrap}
.ttx-sp{flex:1}
.ttx-sb .pill.ttx-del{color:var(--dm-bad)}
@media (hover:hover) and (pointer:fine){.ttx-sb .pill.ttx-del:hover{background:color-mix(in srgb,var(--dm-bad) 10%,transparent);color:var(--dm-bad)}}
.ttx-sc{overflow-x:auto}
.ttx-t{width:100%;border-collapse:collapse;font-size:13px;min-width:560px}
.ttx-t th{height:36px;padding:0 var(--dm-s-2);text-align:left;font-weight:500;font-size:12px;color:var(--dm-muted);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);white-space:nowrap}
.ttx-t th.ck,.ttx-t td.ck{width:36px;padding-left:var(--dm-s-4)}
.ttx-t th.r,.ttx-t td.r{text-align:right}
.ttx-t th:last-child,.ttx-t td:last-child{padding-right:var(--dm-s-4)}
/* a header sorts its column: a quiet arrow shows on hover and stays on the column the rows are sorted by */
.ttx-s{display:inline-flex;align-items:center;gap:3px;height:24px;margin:0 -6px;padding:0 6px;border-radius:calc(6px * var(--dm-rk));color:inherit;font:inherit;transition:color .2s,background-color .2s}
@media (hover:hover) and (pointer:fine){.ttx-s:hover{color:var(--dm-fg);background:var(--dm-row)}}
.ttx-s .ar{display:grid;opacity:0;transition:opacity .2s,transform .35s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.ttx-s:hover .ar{opacity:.45}}
.ttx-s.on{color:var(--dm-fg)}
.ttx-s.on .ar{opacity:1}
.ttx-s.on.desc .ar{transform:rotate(180deg)}
.ttx-t td{height:46px;padding:0 var(--dm-s-2);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);white-space:nowrap}
.ttx-t tbody tr:last-child td{border-bottom:0}
/* rows: the shared hover, and a slightly deeper grey while picked */
.ttx-t tbody tr[data-id]{cursor:pointer;transition:background-color .25s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.ttx-t tbody tr[data-id]:hover{background:var(--dm-row)}}
.ttx-t tbody tr.sel{background:color-mix(in srgb,var(--dm-fg) 6%,transparent)}
@media (hover:hover) and (pointer:fine){.ttx-t tbody tr.sel:hover{background:color-mix(in srgb,var(--dm-fg) 8%,transparent)}}
.ttx-t .nm{font-weight:500}
.ttx-t .ag{display:flex;align-items:center;gap:7px;color:var(--dm-fg2)}
.ttx-t .ag .av{width:20px;height:20px;font-size:9.5px}
.ttx-t td.num{color:var(--dm-fg2)}
.ttx-t td.up{color:var(--dm-muted)}
/* checkboxes: the tick springs in; select-all shows a dash while only some rows are picked */
.ttx-cb{display:grid;place-items:center;width:16px;height:16px;border-radius:5px;box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--dm-muted) 80%,var(--dm-surface));color:var(--dm-on-accent,#fff);transition:background-color .2s,box-shadow .2s}
@media (hover:hover) and (pointer:fine){.ttx-cb:hover{box-shadow:inset 0 0 0 1.5px var(--dm-muted)}}
.ttx-cb[aria-checked="true"],.ttx-cb[aria-checked="mixed"]{background:var(--dm-accent);box-shadow:inset 0 0 0 1px var(--dm-accent-mark,var(--dm-accent))}
.ttx-cb svg{grid-area:1/1;width:11px;height:11px;opacity:0;transform:scale(.4);transition:opacity .15s,transform .3s cubic-bezier(.34,1.4,.64,1)}
.ttx-cb[aria-checked="true"] .ck-y,.ttx-cb[aria-checked="mixed"] .ck-m{opacity:1;transform:none}
/* status: a soft pill in the status colour; Running, Done and Failed have their own, Queued and Paused stay grey */
.ttx-st{--dm-sc:var(--dm-muted);display:inline-flex;align-items:center;height:22px;padding:0 9px 0 7px;border-radius:var(--dm-r-pill);font-size:12px;font-weight:500;color:var(--dm-sc);background:color-mix(in srgb,var(--dm-sc) 11%,transparent);transition:color .35s var(--dm-ease),background-color .35s var(--dm-ease)}
.ttx-st .sv{display:inline-flex;align-items:center;gap:6px}
/* running reads in the accent's text colour on a tint of its mark, so a light accent like lime stays legible */
.ttx-st[data-s="run"]{--dm-sc:var(--dm-accent-fg,var(--dm-accent));background:color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 11%,transparent)}
.ttx-st[data-s="done"]{--dm-sc:var(--dm-ok)}
.ttx-st[data-s="fail"]{--dm-sc:var(--dm-bad)}
.ttx-st .spin{width:10px;height:10px}
/* a new status fades in out of a blur; a cancelled row slides away before it goes */
.ttx-sin{animation:ttxsin .32s var(--dm-ease)}
@keyframes ttxsin{from{opacity:0;filter:blur(3px)}}
.ttx-t tbody tr.ttx-out{opacity:0;transform:translateX(14px);transition:opacity .24s var(--dm-ease),transform .24s var(--dm-ease)}
.ttx-st .i{width:12px;height:12px}
/* when every task is gone */
.ttx-t tbody tr.ttx-empty td{height:auto;padding:36px var(--dm-s-4) 34px;text-align:center;white-space:normal}
.ttx-em{display:flex;flex-direction:column;align-items:center;gap:3px}
.ttx-em .ic{display:grid;place-items:center;width:36px;height:36px;margin-bottom:var(--dm-s-2);border-radius:var(--dm-r-in);background:var(--dm-chip);color:var(--dm-muted)}
.ttx-em b{font-size:13.5px;font-weight:500}
.ttx-em span{font-size:12.5px;color:var(--dm-muted)}
.ttx-em .pill{margin-top:10px}
/* narrow, on a phone or in a narrow card: each task stacks, its name and cost on top and its status, agent and last update
   on a line under it; the header row keeps select all and the sort buttons, and the bulk actions stay in the header above */
@container ttx (max-width:560px){
  .ttx-t{display:block;min-width:0}
  .ttx-t thead,.ttx-t tbody{display:block}
  .ttx-t tr{position:relative;padding:var(--dm-s-3) var(--dm-s-4) var(--dm-s-3) 44px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
  .ttx-t thead tr{display:flex;flex-wrap:wrap;align-items:center;gap:var(--dm-s-1) var(--dm-s-2);padding-top:var(--dm-s-2);padding-bottom:var(--dm-s-2)}
  .ttx-t tbody tr{display:flex;flex-wrap:wrap;align-items:center;gap:var(--dm-s-1) var(--dm-s-3)}
  .ttx-t tbody tr:last-child{border-bottom:0}
  .ttx-t th,.ttx-t td,.ttx-t th:last-child,.ttx-t td:last-child{display:block;height:auto;padding:0;border-bottom:0}
  .ttx-t th.ck,.ttx-t td.ck{position:absolute;left:16px;top:14px;width:auto;padding:0}
  .ttx-t thead th.ck{top:50%;transform:translateY(-50%)}
  .ttx-t td.nm{order:1;flex:1 0 calc(100% - 64px);min-width:0;white-space:normal;line-height:1.45}
  .ttx-t td:nth-child(5){order:2;margin-left:auto;font-size:12px}
  .ttx-t td:nth-child(3){order:3}
  .ttx-t td:nth-child(4){order:4}
  .ttx-t td.up{order:5;margin-left:auto;font-size:12px}
  .ttx-s:not(.on) .ar{display:none}
  .ttx-t tbody tr.ttx-empty{display:block;padding:0}
  .ttx-t tbody tr.ttx-empty td{padding:36px var(--dm-s-4) var(--dm-s-8)}
}
@container ttx (max-width:420px){.ttx-sb{padding-right:var(--dm-s-1)}.ttx-sb .pill{padding:0 var(--dm-s-2)}.ttx-sb .pill .i{display:none}}
@container ttx (max-width:340px){.ttx-ti{padding:0 var(--dm-s-3)}.ttx-sb{gap:0;padding:0 var(--dm-s-1) 0 var(--dm-s-3)}.ttx-n{margin-right:var(--dm-s-1)}.ttx-t tr{padding-left:40px}.ttx-t th.ck,.ttx-t td.ck{left:12px}}

DM.def('task-table', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{pause}', I('pause','xs')).replace('{refresh}', I('refresh','xs')).replace('{x}', I('x','xs'));
  const ST = { run:['Running','<span class="spin"></span>'], done:['Done', I('ok','xs')], fail:['Failed', I('alert','xs')], wait:['Queued','<span class="dot"></span>'], pause:['Paused', I('pause','xs')] };
  const SEED = [
    ['Audit pricing contrast','run','Design','DS','var(--dm-av-b)',0.42,2],
    ['Export tokens to CSS','done','Code','CO','var(--dm-av-m)',0.18,14],
    ['Sync Figma frames','fail','Design','DS','var(--dm-av-b)',0.07,26],
    ['Draft launch email','wait','Writer','WR','var(--dm-av-l)',0,31],
    ['Compare checkout flows','done','Research','RE','var(--dm-av-t)',0.66,48],
    ['Rename layers in Hero','run','Design','DS','var(--dm-av-b)',0.11,5]
  ];
  const seed = () => SEED.map((x, i) => ({ id:i, n:x[0], s:x[1], a:x[2], ai:x[3], ac:x[4], cost:x[5], up:x[6], sel:false }));
  let T = seed();
  const box = $('.ttx', r), tb = $('tbody', r), all = $('.ttx-all', r), sb = $('.ttx-sb', r), sum = $('.ttx-sum', r), cnt = $('.ttx-n', r);
  const ease = getComputedStyle(r).getPropertyValue('--dm-ease').trim() || 'ease';
  const tick = I('check','xs').replace('class="i xs"', 'class="i xs ck-y"') + I('minus','xs').replace('class="i xs"', 'class="i xs ck-m"');
  all.innerHTML = tick;
  $$('.ttx-s', r).forEach(b => b.insertAdjacentHTML('beforeend', `<span class="ar">${I('chev-u','xs')}</span>`));
  let key = 4, desc = false;
  const fields = [t => t.n, t => ['run','fail','wait','pause','done'].indexOf(t.s), t => t.a, t => t.cost, t => t.up];
  const ago = m => m ? m + 'm ago' : 'Just now';
  const face = s => `${ST[s][1]}<span>${ST[s][0]}</span>`, pill = s => `<span class="sv">${face(s)}</span>`;
  // each row is made once and then kept: picking, sorting and actions change it in place, so it can ease between states
  const rows = new Map();
  function make(t){
    const tr = html(`<tr data-id="${t.id}"><td class="ck"><button class="ttx-cb" role="checkbox" aria-checked="false" aria-label="Select ${t.n}">${tick}</button></td><td class="nm">${t.n}</td><td><span class="ttx-st" data-s="${t.s}">${pill(t.s)}</span></td><td><span class="ag">${AV(t.ai, t.ac)}${t.a}</span></td><td class="r num">$${t.cost.toFixed(2)}</td><td class="r num up"><span>${ago(t.up)}</span></td></tr>`);
    tr.onclick = () => { t.sel = !t.sel; sync(); };
    rows.set(t.id, tr); return tr;
  }
  // rows glide to their new places: measured before and after the move, then eased from where they were
  function order(anim){
    const f = fields[key], list = [...T].sort((a, b) => { const x = f(a), y = f(b); return (x > y ? 1 : x < y ? -1 : 0) * (desc ? -1 : 1); });
    const first = anim && !REDUCE ? new Map(list.map(t => [t.id, rows.get(t.id).getBoundingClientRect().top])) : null;
    list.forEach(t => tb.appendChild(rows.get(t.id)));
    if (first) list.forEach(t => { const el = rows.get(t.id), d = first.get(t.id) - el.getBoundingClientRect().top; if (Math.abs(d) > 1) el.animate([{ transform:`translateY(${d}px)` }, { transform:'none' }], { duration:520, easing:ease }); });
    $$('.ttx-s', r).forEach(b => { b.classList.toggle('on', +b.dataset.k === key); b.classList.toggle('desc', desc); b.closest('th').setAttribute('aria-sort', +b.dataset.k === key ? (desc ? 'descending' : 'ascending') : 'none'); });
  }
  let said = '';
  function sync(){
    const n = T.filter(t => t.sel).length;
    T.forEach(t => { const tr = rows.get(t.id); tr.classList.toggle('sel', t.sel); $('.ttx-cb', tr).setAttribute('aria-checked', t.sel); });
    all.setAttribute('aria-checked', n === 0 ? 'false' : n === T.length ? 'true' : 'mixed');
    box.classList.toggle('selecting', n > 0); sb.inert = n === 0; if (n) cnt.textContent = n + ' selected';
    const run = T.filter(t => t.s === 'run').length, line = T.length ? `${T.length} task${T.length === 1 ? '' : 's'}, ${run} running` : 'No tasks';
    if (line !== said){ said ? swap(sum, line) : sum.textContent = line; said = line; }
  }
  const status = (t, s) => { t.s = s; const el = $('.ttx-st', rows.get(t.id)); el.dataset.s = s; el.innerHTML = `<span class="sv ttx-sin">${face(s)}</span>`; };
  // cancelled rows slide away and the rest close up; when nothing is left the table says so
  function leave(ids){
    const out = T.filter(t => ids.includes(t.id)); T = T.filter(t => !ids.includes(t.id));
    // the table's height as it was, for the empty state that takes the last rows' place
    const had = T.length ? 0 : box.getBoundingClientRect().height;
    const go = () => { const first = new Map(T.map(t => [t.id, rows.get(t.id).getBoundingClientRect().top]));
      out.forEach(t => { rows.get(t.id).remove(); rows.delete(t.id); });
      if (!REDUCE) T.forEach(t => { const el = rows.get(t.id), d = first.get(t.id) - el.getBoundingClientRect().top; if (Math.abs(d) > 1) el.animate([{ transform:`translateY(${d}px)` }, { transform:'none' }], { duration:480, easing:ease }); });
      if (!T.length) empty(had); sync(); };
    if (REDUCE) return go();
    out.forEach(t => rows.get(t.id).classList.add('ttx-out'));
    c.later(250, go);
  }
  // the empty state keeps the height the table had, centred in it, so the card doesn't shrink to the top of its stage
  function empty(had){
    const tr = html(`<tr class="ttx-empty"><td colspan="6"><div class="ttx-em"><span class="ic">${I('check')}</span><b>No agent tasks</b><span>Everything has finished or been cancelled.</span><button class="pill ghost sm">${I('refresh','xs')}Bring them back</button></div></td></tr>`);
    tb.appendChild(tr); enter(tr);
    const d = had - box.getBoundingClientRect().height, td = tr.firstElementChild;
    if (d > 1){ const cs = getComputedStyle(td); td.style.paddingTop = parseFloat(cs.paddingTop) + d / 2 + 'px'; td.style.paddingBottom = parseFloat(cs.paddingBottom) + d / 2 + 'px'; }
    $('.pill', tr).onclick = e => { e.stopPropagation(); tr.remove(); T = seed(); T.forEach(make); order(false); sync(); stagger([...tb.children], 30); };
  }
  $$('.ttx-s', r).forEach(b => b.onclick = () => { const k = +b.dataset.k; if (k === key) desc = !desc; else { key = k; desc = false; } order(true); });
  all.onclick = () => { const on = all.getAttribute('aria-checked') !== 'true'; T.forEach(t => t.sel = on); sync(); };
  $('.ttx-clr', r).onclick = () => { T.forEach(t => t.sel = false); sync(); };
  $$('.ttx-sb [data-a]', r).forEach(b => b.onclick = () => {
    const a = b.dataset.a, ids = T.filter(t => t.sel).map(t => t.id);
    T.forEach(t => t.sel = false);
    if (a === 'cancel'){ sync(); leave(ids); return; }
    T.forEach(t => { if (!ids.includes(t.id)) return;
      if (a === 'pause' && (t.s === 'run' || t.s === 'wait')) status(t, 'pause');
      if (a === 'retry' && (t.s === 'fail' || t.s === 'pause')){ status(t, 'run'); t.up = 0; swap($('.up span', rows.get(t.id)), ago(0)); } });
    sync(); if (key === 1 || key === 4) c.later(320, () => order(true));
  });
  T.forEach(make); order(false); sync(); stagger([...tb.children], 30);
  // the preview picks two tasks and retries them, unless you start clicking first
  c.auto(1600, () => { if (T.some(t => t.sel)) return; T.forEach(t => t.sel = t.id === 2 || t.id === 5); sync();
    c.auto(1900, () => { if (T.filter(t => t.sel).length === 2) $('.ttx-sb [data-a="retry"]', r).click(); }); });
});
